import { elements, molecularMass, CLASS_NA, format } from './core.js';
export function foundationLesson(){
 const water=molecularMass('H2O'),carbon=molecularMass('CO2');
 return '<section class="foundation-lesson" aria-labelledby="foundation-title" data-glossary-skip><div class="lesson-section-heading"><span class="eyebrow">從這裡開始 / 三個基礎觀念</span><h3 id="foundation-title">先知道「多重」，再學會「有多少」</h3><p>原子組成分子；莫耳幫我們把看不見的微粒，連到天平上的克數。</p></div><div class="foundation-grid"><article><span class="concept-index">01 / 比較一種原子</span><h4>原子量</h4><div class="atom-mass-tokens"><span><b>H</b><small>氫</small><strong>'+elements.H.ar+'</strong></span><span><b>C</b><small>碳</small><strong>'+elements.C.ar+'</strong></span><span><b>O</b><small>氧</small><strong>'+elements.O.ar+'</strong></span></div><p>把<b>一個碳-12 原子質量的 1/12</b>當作比較標準。元素原子的平均質量除以這個標準，就是相對原子量。</p><p class="concept-key">它是比值，沒有單位。<br>氧的原子量 16，並不是一顆氧原子重 16 g。</p></article><article><span class="concept-index">02 / 加總一個分子</span><h4>分子量</h4><div class="water-molecule" aria-label="一個水分子由兩個氫原子與一個氧原子組成"><i>H</i><b>O</b><i>H</i></div><p>讀化學式的下標，數出每種原子有幾個，再把它們的原子量加起來。</p><div class="concept-formula">H₂O：2 × 1 + 16 = <b>'+water+'</b></div><p class="concept-key">分子量也沒有單位。<br>CO₂：12 + 2 × 16 = '+carbon+'。</p></article><article><span class="concept-index">03 / 數一大群微粒</span><h4>莫耳 <small>mol</small></h4><div class="mole-number"><strong>6.02 × 10<sup>23</sup></strong><span>約這麼多個指定粒子 = 1 mol</span></div><p>就像一打有 12 個，莫耳是物質的量的單位。說「1 mol」時，要指出數的是<b>原子、分子或離子</b>。</p><p class="concept-key">1 mol 水與 1 mol 二氧化碳：<br>分子個數相同，質量不同。</p></article></div><div class="mole-bridge"><div><span class="eyebrow">把三個觀念接起來</span><h4>水的分子量 '+water+' → 莫耳質量約 '+water+' g/mol</h4><p>莫耳質量是每 1 mol 物質的質量。把一杯水的克數除以每莫耳幾克，就得到莫耳數。</p></div><div class="mole-worked"><span>例：36 g 水</span><b>36 g ÷ '+water+' g/mol = 2 mol</b><span>約含 '+format(2*CLASS_NA)+' 個水分子</span></div></div><p class="foundation-footnote">本章使用教學近似值；1 mol 的精確定義為 6.02214076 × 10²³ 個指定粒子。NaCl 等離子化合物沒有獨立分子，依化學式加總的相對質量稱為「式量」。 <a href="https://www.bipm.org/en/si-base-units/mole" target="_blank" rel="noopener">莫耳定義 ↗</a> · <a href="https://www.nist.gov/pml/special-publication-811/nist-guide-si-chapter-8" target="_blank" rel="noopener">相對質量定義 ↗</a></p></section>';
}
export function equationLesson(){return '<section class="equation-primer" data-glossary-skip><div class="lesson-section-heading"><span class="eyebrow">先看示範，再動手配平</span><h3>寫化學反應式的四個步驟</h3></div><ol class="equation-writing"><li><b>確認反應物與生成物</b><p>氫氣和氧氣反應，生成水。先認識物質，不能為了湊數隨意猜化學式。</p></li><li><b>左邊寫反應物，右邊寫生成物</b><p class="concept-formula">H₂ + O₂ → H₂O <small>（尚未配平）</small></p></li><li><b>只改係數，讓各種原子一樣多</b><p class="concept-formula"><em>2</em>H₂ + O₂ → <em>2</em>H₂O</p><p>左右各有 4 個 H、2 個 O。係數 1 省略；H₂O 的下標不能改。</p></li><li><b>標出狀態與需要的條件</b><p>(s) 固體、(l) 液體、(g) 氣體、(aq) 水溶液。加熱、點火或催化劑等條件寫在箭頭旁，依實際反應填寫。</p></li></ol><div class="equation-note"><b>係數比 2：1：2</b><span>表示氫氣、氧氣、水的分子數比或莫耳數比；不是質量比。</span></div></section>';}
